it("matches the item counts the real checklist states", () => {
  const md = fs.readFileSync(path.join(repoRoot(), "h7-platform", "SCHEMATIC-CHECKLIST.md"), "utf8");
  const stated = /\*\*Item count\*\*[^:]*:([^\n]*\n[^\n]*)/.exec(md)?.[1];
  if (stated === undefined) throw new Error("SCHEMATIC-CHECKLIST.md has no Item count line");
  const perPrefix = new Map([...stated.matchAll(/\b([A-Z]+) (\d+)\b/g)].map((m) => [m[1]!, Number(m[2])]));
  const ids = checklistIds(md);
  const actual = new Map<string, number>();
  for (const id of ids) actual.set(id.split("-")[0]!, (actual.get(id.split("-")[0]!) ?? 0) + 1);
  expect(actual).toEqual(perPrefix);
  const schematic = ["CORE", "CODEC", "PWR", "AIO", "CTL", "USB", "ALL"];
  expect(ids.filter((id) => schematic.includes(id.split("-")[0]!))).toHaveLength(Number(/(\d+) schematic items/.exec(stated)?.[1]));
  expect(perPrefix.get("OWN")).toBeGreaterThan(0);
  expect(perPrefix.get("BU")).toBeGreaterThan(0);
});
